package dev.raf.radar;
import android.app.*;import android.graphics.Color;import android.os.*;import android.text.*;import android.text.InputType;import android.view.*;import android.widget.*;import java.util.*;
/** A draft stays local until Save; all controls use the application's theme. */
final class PointEditor {
 final MainActivity a;final Point original,draft;final boolean existing;AlertDialog dialog;EditText name;LinearLayout controls;TextView address,coords;int threshold;
 PointEditor(MainActivity a,Point p){this.a=a;original=p;try{draft=Point.from(p.json());}catch(Exception e){throw new IllegalArgumentException(e);}threshold=draft.threshold;existing=a.store.points().stream().anyMatch(x->x.id.equals(p.id));}
 static void show(MainActivity a,Point p){new PointEditor(a,p).show();}
 void show(){
  LinearLayout root=a.column();root.setPadding(a.dp(18),a.dp(16),a.dp(18),a.dp(12));root.setBackground(Appearance.lineage(a)?Appearance.frame(a,false):a.shape(a.surface,22));
  LinearLayout header=a.row();header.addView(a.heading(draft.dynamic?"Моя геопозиция":"Настройки точки",22),new LinearLayout.LayoutParams(0,-2,1));TextView close=a.primary("×",false,()->dialog.dismiss());close.setContentDescription("Закрыть настройки точки");header.addView(close,new LinearLayout.LayoutParams(a.dp(44),a.dp(44)));root.addView(header);
  ScrollView scroll=new ScrollView(a);scroll.setClipToPadding(false);LinearLayout body=a.column();body.setPadding(0,a.dp(14),0,a.dp(8));scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  if(!draft.dynamic){body.addView(a.text("Название",12,a.muted));name=new EditText(a);name.setSingleLine(true);name.setTextColor(a.fg);name.setHintTextColor(a.muted);name.setTextSize(16);name.setHint("Например, Родник");name.setText(draft.name);name.setFilters(new InputFilter[]{new InputFilter.LengthFilter(80)});name.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);name.setContentDescription("Название точки");name.setPadding(a.dp(12),a.dp(10),a.dp(12),a.dp(10));name.setBackground(Appearance.lineage(a)?Appearance.frame(a,true):a.shape(a.bg,12));LinearLayout.LayoutParams np=new LinearLayout.LayoutParams(-1,a.dp(50));np.topMargin=a.dp(6);np.bottomMargin=a.dp(16);body.addView(name,np);}
  LinearLayout location=a.column();location.setPadding(a.dp(12),a.dp(12),a.dp(12),a.dp(12));location.setBackground(Appearance.lineage(a)?Appearance.frame(a,false):a.shape(a.bg,14));location.addView(a.text(draft.dynamic?"Местоположение телефона":"Место",12,a.muted));
  address=a.text(a.pointAddress(draft),14,a.fg);address.setMaxLines(3);address.setPadding(0,a.dp(6),0,a.dp(4));location.addView(address);coords=a.text(coordinates(),11,a.muted);location.addView(coords);TextView value=a.heading("Надбавка · "+RadarUi.value(a.displayReading(original)),18);value.setPadding(0,a.dp(12),0,a.dp(4));location.addView(value);
  if(!draft.dynamic){TextView move=a.primary("Взять центр карты",false,()->{if(a.map==null)return;org.maplibre.android.geometry.LatLng target=a.map.getCameraPosition().target;if(target==null)return;draft.lat=target.getLatitude();draft.lon=target.getLongitude();draft.address="";coords.setText(coordinates());address.setText("Новое место · сохраните изменения");value.setText("Надбавка · —");final double lat=draft.lat,lon=draft.lon;a.resolveAddress(lat,lon,result->{if(dialog!=null&&dialog.isShowing()&&draft.lat==lat&&draft.lon==lon){draft.address=result;address.setText(result);}});});move.setTextSize(12);LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(-1,a.dp(44));mp.topMargin=a.dp(8);location.addView(move,mp);}body.addView(location);
  a.switchRow(body,"Обновлять точку",draft.enabled,0,on->draft.enabled=on);
  a.switchRow(body,"Уведомлять о надбавке",draft.notify,0,on->{draft.notify=on;controls.setVisibility(on?View.VISIBLE:View.GONE);});
  controls=a.column();controls.setVisibility(draft.notify?View.VISIBLE:View.GONE);TextView level=a.text("От "+threshold+" ₽",14,a.fg);controls.addView(level);SeekBar slider=new SeekBar(a);slider.setContentDescription("Порог уведомлений");slider.setMax(20);slider.setProgress(Math.max(0,Math.min(20,threshold/50)));slider.setProgressTintList(android.content.res.ColorStateList.valueOf(Appearance.accent(a)));slider.setThumbTintList(android.content.res.ColorStateList.valueOf(Appearance.accent(a)));slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int n,boolean user){if(user){threshold=n*50;level.setText("От "+threshold+" ₽");}}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});controls.addView(slider);controls.addView(a.text("Повтор через 30 минут. При росте ещё на 50 ₽ — сразу.",12,a.muted));body.addView(controls);
  if(existing&&!draft.dynamic){TextView remove=a.text("Удалить точку",13,0xFFFF7D87);remove.setGravity(Gravity.CENTER);remove.setMinHeight(a.dp(44));remove.setOnClickListener(v->new AlertDialog.Builder(a).setTitle("Удалить точку?").setMessage(draft.name).setNegativeButton("Отмена",null).setPositiveButton("Удалить",(d,w)->{a.store.remove(draft.id);AppSounds.play(a,AppSounds.Event.POINT_DELETE);a.hidePreview();a.refreshCards();dialog.dismiss();}).show());body.addView(remove);}
  LinearLayout footer=a.row();LinearLayout.LayoutParams left=new LinearLayout.LayoutParams(0,a.dp(48),1);left.rightMargin=a.dp(8);footer.addView(a.primary("Отмена",false,()->dialog.dismiss()),left);footer.addView(a.primary("Сохранить",true,this::save),new LinearLayout.LayoutParams(0,a.dp(48),1));root.addView(footer);
  dialog=new AlertDialog.Builder(a).setView(root).create();dialog.setOnShowListener(d->{dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);dialog.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);dialog.getWindow().setLayout(Math.min(a.getResources().getDisplayMetrics().widthPixels-a.dp(24),a.dp(560)),Math.min((int)(a.getResources().getDisplayMetrics().heightPixels*.84f),a.dp(650)));});dialog.show();
 }
 String coordinates(){return draft.dynamic?"По свежей геопозиции":String.format(Locale.US,"%.5f, %.5f",draft.lat,draft.lon);}
 void save(){String value=draft.dynamic?"Моя геопозиция":name.getText().toString().trim();if(value.isEmpty()){name.setError("Укажите название");name.requestFocus();return;}draft.name=value;draft.threshold=threshold;draft.tariffs=new ArrayList<>(Collections.singletonList("econom"));boolean moved=draft.lat!=original.lat||draft.lon!=original.lon;a.store.update(draft);if(moved&&!draft.dynamic)a.store.readings(draft.id,Collections.emptyList());Statistics.syncSources(a);if(!existing)AppSounds.play(a,AppSounds.Event.POINT_SAVE);a.selected=draft.id;a.hidePreview();a.refreshCards();dialog.dismiss();}
}
